INSERT INTO "public"."products" ("id", "category_id", "name", "sku", "description", "images", "original_price", "discount_percent", "sale_price", "specs", "is_featured", "is_published", "order_index", "created_at", "slug", "updated_at", "brand_id", "deleted_at", "stock_status", "meta_title", "meta_description") VALUES ('004ed92a-e923-4065-a892-a1e269e50211', 'a7afe42a-414a-4a57-b459-f03a1a542fc8', 'Máy lạnh treo tường Daikin 2HP - hai chiều Inverter', 'FTHF50VAVMV / RHF50VAVMV', '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Luồng gió thoải mái Coanda","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Luồng gió Coanda trên máy điều hòa Daikin được tạo ra nhờ thiết kế mặt nạ độc đáo có một góc cong ở miệng gió trên dàn lạnh. ","type":"text"}]},{"type":"paragraph","content":[{"text":"Thiết kế này vận dụng từ hiện tượng khoa học Coanda, khiến luồng hơi lạnh phả ra từ miệng gió được đẩy lên trần nhà rồi nhịp nhàng tỏa xuống, bao phủ toàn bộ khắp gian phòng.","type":"text"}]},{"type":"paragraph","content":[{"text":"Chi tiết thiết kế tinh tế này giúp máy điều hòa Daikin mang lại sự thoải mái dễ chịu cho người dùng vì không trực tiếp thổi gió vào một khu vực mà phân bổ khí tươi mát đều khắp gian phòng cho toàn bộ người sử dụng trong gian phòng. ","type":"text"}]},{"type":"paragraph"},{"type":"image","attrs":{"alt":"Luồng gió thoải mái Coanda","src":"https://api-shop.daikin.com.vn:60443/storage/upload/media/San%20Pham/Dieu%20Hoa%20Dan%20Dung/2%20Dan%20Roi/FTHF/COANDA-800x600_COANDA.jpg","title":null,"width":"100%","height":"auto"}},{"type":"paragraph","content":[{"text":"Công Nghệ Inverter","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Bạn có biết máy nén là bộ phận phát ra nhiều tiếng ồn nhất và tiêu tốn nhiều điện năng nhất trong chiếc máy điều hòa vì đây là bộ phận đảm nhận nén và luân chuyển dòng môi chất lạnh? ","type":"text"}]},{"type":"paragraph","content":[{"text":"Khác với các hãng sản xuất máy điều hòa Inverter dựa trên máy nén quay truyền thống hoạt động theo chuyển động lò xo dập lên xuống, Daikin sử dụng máy nén Swing độc quyền cho công nghệ Inverter. ","type":"text"}]},{"type":"paragraph","content":[{"text":"Máy nén Swing có thiết kế nguyên khối, chuyển động quay tròn nhẹ nhàng giúp giảm đáng kể ma sát và rung động khi vận hành, không rò rỉ môi chất làm lạnh khi sử dụng.","type":"text"}]},{"type":"paragraph","content":[{"text":"Nhờ vậy, máy nén Swing giúp tiết kiệm chi phí sử dụng và vận hành êm hơn. Cụ thể, điều hòa INVERTER giúp tiết kiệm dài hạn. Đồng thời, cải tiến độ ồn dàn nóng và dàn lạnh giúp máy hoạt động êm ái, duy trì nhiệt độ ổn định và đạt công suất tối ưu.","type":"text"}]},{"type":"paragraph","content":[{"text":"(*) Chi phí điện năng trong vòng 1 năm, theo tính toán của Daikin Vietnam.","type":"text"}]},{"type":"paragraph"},{"type":"image","attrs":{"alt":"Công Nghệ Inverter","src":"https://api-shop.daikin.com.vn:60443/storage/upload/media/San%20Pham/Dieu%20Hoa%20Dan%20Dung/2%20Dan%20Roi/FTHF/cong-nghe--inverter.PNG","title":null,"width":"100%","height":"auto"}},{"type":"paragraph","content":[{"text":"Mắt Thần Thông Minh Tiêu Chuẩn","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Mắt thần thông minh sử dụng cảm biến hồng ngoại để tự động điều chỉnh hoạt động của máy điều hòa, dựa vào sự chuyển động của người trong phòng. Nếu không có chuyển động trong vòng 20 phút, máy sẽ tự động điều chỉnh cài đặt lên khoảng 2°C để tiết kiệm điện năng.","type":"text"}]},{"type":"paragraph"},{"type":"image","attrs":{"alt":"Mắt Thần Thông Minh Tiêu Chuẩn","src":"https://api-shop.daikin.com.vn:60443/storage/upload/media/San%20Pham/Dieu%20Hoa%20Dan%20Dung/2%20Dan%20Roi/FTHF/mat%20than%20thong%20minh%20tieu%20chuan@300x-100%20(1).jpg","title":null,"width":"100%","height":"auto"}},{"type":"paragraph","content":[{"text":"Phin Lọc Apatit Titan","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Phin lọc này như một lá chắn bảo vệ, đưa ra một giải pháp tối ưu nhằm mang lại bầu không khí trong lành, loại bỏ mùi hôi và chất gây dị ứng. Trong điều kiện bảo dưỡng phù hợp, phin lọc này có thể sử dụng lên đến 3 năm.","type":"text"}]},{"type":"paragraph"},{"type":"image","attrs":{"alt":"Phin Lọc Apatit Titan","src":"https://api-shop.daikin.com.vn:60443/storage/upload/media/San%20Pham/Dieu%20Hoa%20Dan%20Dung/2%20Dan%20Roi/FTHF/phin%20loc%20apatittitan.png","title":null,"width":"100%","height":"auto"}},{"type":"paragraph","content":[{"text":"Bảo Vệ Điện Áp Cao - Thấp","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Tính năng này bao gồm một mạch điện tử có độ bền cao được lắp trong dàn nóng. ","type":"text"},{"type":"hardBreak"},{"text":"Khi điện áp trồi sụt bất thường, mạch này sẽ bảo vệ động cơ quạt và máy nén mà người sử dụng không cần phải lắp thêm bộ ổn áp điện. ","type":"text"},{"type":"hardBreak"},{"text":"Cụ thể, trong khoảng điện áp từ 130-264V: máy hoạt động bình thường. Trên 264-440V: máy lạnh sẽ tự dừng lại, ngắt điện để ko hư máy. ","type":"text"}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"text":"Lưu ý: chỉ bảo vệ điện áp 1 pha.","type":"text"}]},{"type":"paragraph"},{"type":"image","attrs":{"alt":"Bảo Vệ Điện Áp Cao - Thấp","src":"https://api-shop.daikin.com.vn:60443/storage/upload/media/San%20Pham/Dieu%20Hoa%20Dan%20Dung/2%20Dan%20Roi/FTHF/do%20ben%20cao-baovebomach.png","title":null,"width":"100%","height":"auto"}},{"type":"paragraph","content":[{"text":"Dàn Tản Nhiệt Ống Đồng Cánh Nhôm Chống Ăn Mòn","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Cánh trao đổi nhiệt được áp dụng các cách xử lý chống ăn mòn đặc biệt: được sơn bằng 02 lớp sơn tĩnh điện, bề mặt cánh còn được phủ một lớp nhựa acrylic mỏng để tăng khả năng chống mưa acid và sự ăn mòn của muối gió biển.","type":"text"}]},{"type":"paragraph"},{"type":"image","attrs":{"alt":"Dàn Tản Nhiệt Ống Đồng Cánh Nhôm Chống Ăn Mòn","src":"https://api-shop.daikin.com.vn:60443/storage/upload/media/San%20Pham/Dieu%20Hoa%20Dan%20Dung/2%20Dan%20Roi/FTHF/tan%20nhiet%20ong%20dong%20canh%20nhom.png","title":null,"width":"100%","height":"auto"}},{"type":"paragraph","content":[{"text":"Sưởi ấm","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Máy điều hòa hai chiều có dải công suất rộng từ 2.5kW-7.1kW giúp bạn dễ dàng lựa chọn các dòng máy phù hợp với diện tích căn phòng. Luồng gió sẽ được luân chuyển đều khắp phòng, gia tăng sự thoải mái với không gian dễ chịu và ấm áp.","type":"text"}]},{"type":"paragraph"},{"type":"image","attrs":{"alt":"Sưởi ấm","src":"https://api-shop.daikin.com.vn:60443/storage/upload/media/San%20Pham/Dieu%20Hoa%20Dan%20Dung/2%20Dan%20Roi/FTHF/che%20do%20suoi%20am-1%20(1).png","title":null,"width":"100%","height":"auto"}}]}', ARRAY['https://gdzihzsjfczuggwpykjk.supabase.co/storage/v1/object/public/images/products/1775815743868-reytr38yf7.webp','https://gdzihzsjfczuggwpykjk.supabase.co/storage/v1/object/public/images/products/1775815764779-dziq2jpn4k.webp','https://gdzihzsjfczuggwpykjk.supabase.co/storage/v1/object/public/images/products/1775815765531-laxn8jaq67.webp','https://gdzihzsjfczuggwpykjk.supabase.co/storage/v1/object/public/images/products/1775815766293-k94v36an0y.webp','https://gdzihzsjfczuggwpykjk.supabase.co/storage/v1/object/public/images/products/1775815774010-iij57ddd5pg.webp','https://gdzihzsjfczuggwpykjk.supabase.co/storage/v1/object/public/images/products/1775815778912-cg9xz2yqllr.webp'], '21657408', '0.00', '21657408', '[{"label":"Công nghệ Inverter","value":"Có"},{"items":[{"unit":"HP","label":"","value":"2  "},{"unit":"kW","label":"","value":"5.6"},{"unit":"BTU","label":"","value":"17.100"}],"label":"Công suất làm lạnh"},{"items":[{"unit":"w","label":"","value":"1.31"}],"label":"Điện năng tiêu thụ"},{"items":[{"unit":"m2","label":"","value":"<=30"}],"label":"Phạm vi làm lạnh hiệu quả"},{"label":"Tiết kiệm điện","value":"★★★★★"},{"label":"Hiệu suất năng lượng (CSPF)","value":"6.3"},{"label":"THÔNG TIN DÀN LẠNH","value":" FTHF50VAVMV"},{"items":[{"unit":"mm","label":"","value":"990x 295x 281"}],"label":"Kích thước HxWxD"},{"items":[{"unit":"kg","label":"","value":"13"}],"label":"Trọng lượng"},{"items":[{"unit":"dba","label":"","value":"28/44"}],"label":"Độ ồn (Cao / Cực thấp)"},{"label":"THÔNG TIN DÀN NÓNG","value":"RHF50VAVMV"},{"items":[{"unit":"mm","label":"","value":" 845x 595x 300"}],"label":"Kích thước HxWxD"},{"items":[{"unit":"kg","label":"","value":"36"}],"label":"Trọng lượng"},{"items":[{"unit":"dba","label":"","value":"44/47"}],"label":"Độ ồn (Cao / Cực thấp)"},{"label":"THÔNG TIN CHUNG","value":"FTHF50VAVMV / RHF50VAVMV"},{"label":"Môi chất lạnh","value":"R32"},{"items":[{"unit":"m","label":"","value":"30"}],"label":"Chiều dài tối đa"},{"items":[{"unit":"m","label":"","value":"20"}],"label":"Chênh lệch độ cao tối đa"},{"label":"Xuất xứ","value":"Việt Nam"}]', false, true, 36, '2026-04-10 10:09:48.515948+00', 'daikin-2hp-fthf50vavmv', '2026-05-13 00:05:50.848846+00', 'c596457f-52bd-4284-8e6d-929e7a978716', null, 'in_stock', null, null), ('01fcd580-c064-4156-83fb-3a7a40f525b7', 'be38717c-1a6c-4766-8f6e-75f43ba7a230', 'Máy lạnh áp trần DaiKin inverter 5.5HP ( 1 pha )', 'FHA140CVMA / RZA140DV1 + BRC1H63W', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Thiết kế nhỏ gọn, công suất 48000btu","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Điều hòa áp trần Đaikin FHA140BVMA/RZA140DV1 thuộc dòng máy ","type":"text"},{"text":"điều hòa 2 chiều","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://dienmayhanhung.vn/?post_type=product&p=14722&preview=true","class":"text-primary underline underline-offset-4 cursor-pointer","title":null,"target":"_blank"}}]},{"text":", công suất lạnh 48000btu có thể đáp ứng nhu cầu sử dụng cho những không gian có diện tích từ 40 đến dưới 45m2 như nhà hàng, văn phòng, phòng họp… Máy có kích thước nhỏ gọn, thiết kế hiện đại có thể kết hợp với nhiều không gian nội thất khác nhau.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Phân phối không khí trong lành khắp không gian phòng","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Điều hòa áp trần Đaikin 2 chiều FHA140BVMA/RZA140DV1 có thể đảo gió tự động (lên-xuống) mang tới sự thoải mái cho cả căn phòng. Miệng gió cải tiến với thiết kế mở rộng giúp phân tán luồng gió với góc mở lên tới 100 độ. Không chỉ thế, gió được thổi hướng xuống với góc 50 độ. Chế độ “Làm khô” được điều khiển bằng bộ vi xử lý để hạn chế những sự thay đổi đột ngột và khó chịu về nhiệt độ không khí.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Công nghệ Inverter tiết kiệm điện","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Không chỉ mang đến khả năng làm lạnh vô cùng bền bỉ, hoạt động êm ái, chiếc máy điều hòa áp trần ","type":"text"},{"text":"Daikin","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://dienmayhanhung.vn/?post_type=product&p=14722&preview=true","class":"text-primary underline underline-offset-4 cursor-pointer","title":null,"target":"_blank"}}]},{"text":" 2 chiều FHA140BVMA/RZA140DV1 với công nghệ Inverter còn duy trì nhiệt độ phòng luôn được ổn định, đồng thời tiết kiệm điện năng hiệu quả cho bạn.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Vận hành êm ái","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Máy điều hòa","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://dienmayhanhung.vn/?post_type=product&p=14722&preview=true","class":"text-primary underline underline-offset-4 cursor-pointer","title":null,"target":"_blank"}}]},{"text":" áp trần Đaikin inverter 48000btu FHA140BVMA/RZA140DV1 thế hệ mới của Daikin đã được cải tiến và giảm độ ồn rất nhiều so với thế hệ trước. Nhờ đó mà điều hòa hoạt động êm ái, mang tới không gian yên tĩnh cùng trải nghiệm tốt hơn, nhất là các không gian thương mại. Tốc độ quạt có thể điều chỉnh 3 mức: thấp, trung bình, cao để phù hợp với nhu cầu sử dụng.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Cánh tản nhiệt dàn nóng được xử lý chống ăn mòn","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Để nâng cao độ bền bằng cách cải thiện khả năng chịu đựng ăn mòn do muối và ô nhiễm không khí, dàn lạnh ","type":"text"},{"text":"điều hòa áp trần","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://dienmayhanhung.vn/may-say-quan-ao-bosch-8kg-wth85008sg-series-4/","class":"text-primary underline underline-offset-4 cursor-pointer","title":null,"target":"_blank"}}]},{"text":" Daikin 2 chiều 48000btu FHA140BVMA/RZA140DV1 trao đổi nhiệt được xử lý chống ăn mòn (đã được xử lý sơ bộ bằng acryl) được sử dụng cho dàn trao đổi nhiệt tại dàn nóng.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Tích hợp bơm thoát nước","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Máy điều hòa áp trần Daikin inverter 2 chiều 48000btu FHA140BVMA/RZA140DV1 được tích hợp bơm xả tiêu chuẩn nhà máy theo chiều cao lên tới 850 mm với chất ức chế tăng trưởng vi khuẩn trong hệ thống thoát nước của điều hòa.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Môi chất lạnh R32","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Điều hòa áp trần Đaikin giá rẻ inverter 2 chiều 48000btu FHA140BVMA/RZA140DV1 sử dụng môi chất lạnh R32, đây là môi chất được sử dụng phổ biến nhất hiện nay trên các dòng máy điều hòa thương mại. Với nhiều ưu điểm như: làm lạnh sâu, làm lạnh nhanh, thân thiện với môi trường, không phát thải chất gây nên hiệu ứng nhà kính…","type":"text"}]},{"type":"paragraph"}]}', ARRAY['https://gdzihzsjfczuggwpykjk.supabase.co/storage/v1/object/public/images/products/1776912930763-i0pseir9gtd.webp'], '64185000', '8.00', null, '[{"label":"Xuất xứ","value":"Thái Lan"},{"label":"Môi chất lạnh","value":"R32"},{"label":"Loại máy","value":"điều hòa áp trần inverter – 2 chiều lạnh"},{"items":[{"label":"","value":"5.5 HP"},{"label":"","value":"48000 btu"}],"label":"Công suất"},{"items":[{"label":"","value":"1 pha"},{"label":"","value":"220-240 V"},{"label":"","value":"50-60 Hz"}],"label":"Nguồn điện sử dụng"},{"label":"Phạm vi làm lạnh ","value":"40 - 45 m²"},{"label":"Dàn lạnh","value":"FHA140BVMA"},{"label":"Kích thước dàn lạnh","value":"235X1590X690 mm"},{"label":"Trọng lượng dàn lạnh","value":"38 kg"},{"label":"Dàn nóng","value":"RZA140DV1"},{"label":"Kích thước dàn nóng","value":"1430X940X320 mm"},{"label":"Trọng lượng dàn nóng:","value":"93 kg"},{"label":"Ống Lỏng / Hơi","value":"Ø9.5/ Ø15.9 mm"}]', false, true, 126, '2026-04-23 02:54:19.10537+00', 'daikin-55hp-fha140cvma', '2026-05-13 00:05:43.9669+00', 'c596457f-52bd-4284-8e6d-929e7a978716', null, 'in_stock', null, null), ('0279ddb4-0f1e-496a-96ac-48efedab8ab4', 'be38717c-1a6c-4766-8f6e-75f43ba7a230', 'Máy lạnh áp trần DaiKin 4HP ( 1 pha )', 'FHNQ36MV1V / RNQ36MV1V + BRC1NU61', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"text":"Máy lạnh áp trần Daikin FHNQ36MV1 (4.0Hp)","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"https://dienlanhlepham.vn/may-lanh-ap-tran-daikin-fhnq36mv1-4-0hp/","class":"text-blue-600 underline cursor-pointer","title":null,"target":"_blank"}},{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Hệ thống cải tiến gọn nhẹ và vận hành êm ái","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Phân phối không khí trong lành khắp không gian phòng","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Lắp đặt dễ dàng mang lại sự linh hoạt trong thiết kế","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Vận hành êm ái","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Dễ dàng bảo dưỡng","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Lưới lọc bụi chịu dầu cải tiến","type":"text"}]}]}]},{"type":"paragraph"},{"type":"image","attrs":{"alt":"Daikin FHNQ36MV1 (4.0Hp) ","src":"https://dienlanhlepham.vn/wp-content/uploads/2023/02/lanh_ap_tran_daikin_fhnq.jpg","title":null,"width":935,"height":1223}},{"type":"paragraph","content":[{"text":"Daikin FHNQ36MV1 (4.0Hp)","type":"text","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"text":"Phần tán không khí trong lành khắp không gian phòng","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Đảo gió tự động ( lên & xuống) mang lại sự thoải mái cho khắp cả phòng.","type":"text"},{"type":"hardBreak"},{"text":"Miệng gió rộng giúp phân tán luồng gió với góc mở 100 độ.","type":"text"},{"type":"hardBreak"},{"text":"Gió được thổi hướng xuống với góc 50 độ.","type":"text"},{"type":"hardBreak"},{"text":"Có thể lắp trên trần cao 3.5 m.","type":"text"},{"type":"hardBreak"},{"text":"Tốc độ quạt có thể điều chỉnh: Cao/ Thấp.","type":"text"},{"type":"hardBreak"},{"text":"Chế độ “Làm khô”: Chế độ làm khô của điều hòa áp trần Daikin được điều khiển bằng vi xử lý để hạn chế những thay đổi đột ngột và khó chịu về nhiệt độ không khí trong phòng.","type":"text"}]},{"type":"paragraph"},{"type":"image","attrs":{"alt":"Daikin FHNQ36MV1 (4.0Hp) ","src":"https://dienlanhlepham.vn/wp-content/uploads/2023/02/mieng_gio_ap_tran_daikin.jpg","title":null,"width":1063,"height":568}},{"type":"paragraph","content":[{"text":"Daikin FHNQ36MV1 (4.0Hp)","type":"text","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"text":"Hoạt đông êm ái với tiếng ồn nhỏ nhất cho dòng điều hòa áp trần Daikin","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph"},{"type":"image","attrs":{"alt":"Daikin FHNQ36MV1 (4.0Hp) ","src":"https://dienlanhlepham.vn/wp-content/uploads/2023/02/hoat_dong_em_dieu_hoa_daikin_ap_tran.jpg","title":null,"width":712,"height":698}},{"type":"paragraph","content":[{"text":"Daikin FHNQ36MV1 (4.0Hp)","type":"text","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"text":"Lắp đặt điều hòa áp tràn Daikin một cách linh hoạt và dễ dàng bởi kích thước luôn phù hợp với công trình của bạn:","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph"},{"type":"image","attrs":{"alt":"Daikin FHNQ36MV1 (4.0Hp) ","src":"https://dienlanhlepham.vn/wp-content/uploads/2023/02/lap_dat_dieu_hoa_daikin_ap_tran.jpg","title":null,"width":987,"height":508}},{"type":"paragraph","content":[{"text":"Daikin FHNQ36MV1 (4.0Hp)","type":"text","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"text":"Độ cao và chiều sâu đồng nhất các model công suất nhỏ có kích thước nhỏ hơn phù hợp với không gian hẹp.","type":"text"}]},{"type":"paragraph","content":[{"text":"Việc đấu nối dây và thao tác bên trong đều được thực hiện thuận tiện từ phía dưới Điều hoà.","type":"text"}]},{"type":"paragraph","content":[{"text":"Dể dàng đấu nối đường ống thông qua việc sử dụng miếng nhựa để che các lổ ống, nên có thể mở các lỗ ống dễ dàng mà không cần đến thiết bị chuyên dụng.","type":"text"}]},{"type":"paragraph","content":[{"text":"Dễ dàng bảo dưỡng dòng điều hòa áp trần Daikin:","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Phin lọc tuổi thọ cao dùng trong 01 năm:","type":"text"}]},{"type":"paragraph","content":[{"text":"(với mật độ bụi 0,15mg/m3)","type":"text","marks":[{"type":"italic"}]},{"type":"hardBreak"},{"text":"Hai lựa chọn phin lọc với thời gian ( 2500 giờ và 1250 giờ) có sẵn để phù hợp với môi trường lắp đặt, tín hiệu thời gian bảo dưỡng hiển thị trên điều khiển từ xa ( Tín hiệu phin lọc).","type":"text"},{"type":"hardBreak"},{"text":"Phin lọc phải được vệ sinh sau 01 năm sử dụng.","type":"text"},{"type":"hardBreak"},{"text":"Cánh Đảo gió không nghiêng","type":"text"},{"type":"hardBreak"},{"text":"Nước ngưng tụ và bụi bẩn khó bám vào cánh đảo gió không nghiêng, giúp dễ làm sạch sản phẩm.","type":"text"},{"type":"hardBreak"},{"text":"Bề mặt phẳng, dễ vệ sinh hơn","type":"text"},{"type":"hardBreak"},{"text":"Có thể dễ dàng lau sạch bụi bẩn trên các bề mặt phẳng và mặt dưới của máy.","type":"text"},{"type":"hardBreak"},{"text":"Thao tác bảo trì được thực hiện dễ dàng từ bên dưới","type":"text"}]},{"type":"paragraph","content":[{"text":"Lưới lọc bụi chịu dầu cải tiến:","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Lưới lọc bụi làm bằng nhựa cao cấp chịu được dầu giúp cho sản phẩm bền hơn khi hoạt động trong môi trường nhà hàng và các môi trường khác tương tự","type":"text"}]},{"type":"paragraph","content":[{"text":"( lưu ý: Model nói trên phù hợp gắng trong nhà hàng cửa hàng thông thường, không phù hợp trong bếp nấu và môi trường khắc nghiệt khác)","type":"text","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"text":"Vận hành êm ái với máy lạnh Daikin SkyAir","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Tùy vào từng chủng loại Điều hoà mà độ ồn giao động từ 32 dB(A) đến 45 dB(A).","type":"text"},{"type":"hardBreak"},{"text":"Máy lạnh vận hành ở mức độ ồn từ 48 dB(A) đến 58 dB(A).","type":"text"},{"type":"hardBreak"},{"text":"Dữ liệu dựa trên “Ví dụ về các mức độ âm thanh”, Bộ Môi Trường Nhật Bản, 12/11/2002","type":"text"}]},{"type":"paragraph","content":[{"text":"Cánh tản nhiệt Máy lạnh được xử lý chống ăn mòn","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Để nâng cao độ bền bằng cách cải thiện khả năng chịu đựng ăn mòn do muối và ô nhiễm không khí, dàn trao đổi nhiệt được xử lý chống ăn mòn (đã được xử lý sơ bộ bằng acryl) được sử dụng cho dàn trao đổi nhiệt tại Máy lạnh.","type":"text"}]},{"type":"paragraph","content":[{"text":"Thông số kỹ thuât dòng máy lạnh áp trần Daikin SkyAir FHNQ","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph"},{"type":"image","attrs":{"alt":"Daikin FHNQ36MV1 (4.0Hp) ","src":"https://dienlanhlepham.vn/wp-content/uploads/2023/02/thong_so_ap_tran_daikin_30_48.jpg","title":null,"width":1404,"height":941}}]}', ARRAY['https://gdzihzsjfczuggwpykjk.supabase.co/storage/v1/object/public/images/products/1776681984875-lntz0hau208.webp'], '38423000', '8.00', null, '[{"label":"Xuất xứ","value":"Thái Lan"},{"label":"Loại Gas lạnh\\t","value":"R410A"},{"label":"Loại máy\\t","value":"Không inverter (không tiết kiệm điện) - loại 1 chiều (chỉ làm lạnh)"},{"items":[{"label":"","value":"4.0 Hp (4.0 Ngựa)"},{"label":"","value":"35.000 Btu/h"}],"label":"Công suất làm lạnh\\t "},{"items":[{"label":"","value":"50 - 54 m²"},{"label":"","value":"150 - 162 m³ "}],"label":"Sử dụng cho phòng"},{"items":[{"label":"","value":"1 Pha"},{"label":"","value":"220 - 240 V"},{"label":"","value":"50Hz"}],"label":"Nguồn điện (Ph/V/Hz)"},{"label":"Công suất tiêu thụ điện\\t","value":"3,64 kW"},{"label":"Kích thước ống đồng Gas","value":"9.5 / 15.9 (mm)\\t"},{"label":"Chiều dài ống gas tối đa (m)\\t","value":"50 (m)"},{"label":"Chênh lệch độ cao (tối đa) (m)\\t","value":"30 (m)"},{"label":"Hiệu suất năng lượng CSPF\\t","value":"3.12"},{"label":"DÀN LẠNH","value":"FHNQ36MV1"},{"label":"Kích thước Điều hoà","value":"195 x 1.590 x 680 (mm)"},{"label":"Trọng lượng Điều hoà","value":"35 (Kg)"},{"label":"DÀN NÓNG","value":"RNQ36MV1"},{"label":"Kích thước Máy lạnh","value":"1.345 x 900 x 320 (mm)  "},{"label":"Trọng lượng Máy lạnh","value":"103 (Kg)"}]', false, true, 88, '2026-04-20 10:46:32.612804+00', 'daikin-4hp-fhnq36mv1v', '2026-05-13 00:05:48.01677+00', 'c596457f-52bd-4284-8e6d-929e7a978716', null, 'in_stock', null, null), ('070759ed-8885-445e-93a6-ec09d19c7e17', 'a7afe42a-414a-4a57-b459-f03a1a542fc8', 'Máy lạnh treo tường Daikin 1HP - một chiều Inverter', 'FTKY25ZVMV / RKY25ZVMV', '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Điều hòa Daikin FTKY 2025 - Thêm điều khiển wifi, nâng tầm trải nghiệm","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Điều hòa Daikin Inverter FTKY chắc chắn sẽ là sự lựa chọn hoàn hảo cho gia đình bạn khi được trang bị công nghệ Streamer độc quyền của Daikin và phin lọc Enzyme Blue kết hợp PM2.5 giúp mang đến trải nghiệm không khí mát mẻ, trong lành sạch khuẩn nhất. Ngoài ra, dòng FTKY-ZVMV mới 2025 còn được tích hợp sẵn wifi để điều khiển qua app. Với nhiều tính năng ưu việt, đây chắc chắn là sản phẩm không thể thiếu với mỗi gia đình, cho trải nghiệm khí sạch mát lành trọn vẹn nhất.","type":"text"}]},{"type":"paragraph","content":[{"text":"Điều khiển thông minh với D-Mobile","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Kết nối wifi được tích hợp sẵn ở dòng điều hòa FTKY 2025, bạn dễ dàng điều khiển từ xa hoặc điều khiển bằng giọng nói nhờ sử dụng app D-mobile mọi lúc mọi nơi. Bạn dễ dàng bật/tắt máy, điều chỉnh nhiệt độ, tốc độ quạt hay thậm chí là lập lịch hoạt động hằng tuần hay hẹn giờ mở máy trước khi về nhà. D-mobile mang đến sự tiện lợi và thoải mái hơn bao giờ hết (Hình ảnh mang tính minh hoạ)","type":"text"}]},{"type":"paragraph"},{"type":"image","attrs":{"alt":"Điều khiển thông minh với D-Mobile","src":"https://api-shop.daikin.com.vn:60443/storage/upload/media/SKUs/RA/FTKY-Z/Thong%20tin%20san%20pham/wifi-ky.png","title":null,"width":null,"height":null}},{"type":"paragraph","content":[{"text":"Chống ẩm mốc với công nghệ Streamer","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Hơi ẩm còn lại bên trong dàn lạnh là điều kiện thuận lợi cho vi khuẩn sinh sôi phát triển và gây mùi khó chịu. Với công nghệ chống ẩm mốc trên điều hòa Daikin, sau khi tắt máy, trong vòng 1 giờ quạt sẽ hoạt động để giải quyết tình trạng này. Đây là cách dàn lạnh tự vệ sinh, cho hệ hô hấp khỏe mạnh và tuổi thọ của máy thêm bền lâu.","type":"text"}]},{"type":"paragraph","content":[{"text":"(hình ảnh chỉ mang tính chất minh họa)","type":"text","marks":[{"type":"italic"}]}]},{"type":"paragraph"},{"type":"image","attrs":{"alt":"Chống ẩm mốc với công nghệ Streamer","src":"https://api-shop.daikin.com.vn:60443/storage/upload/media/SKUs/RA/FTKY-Z/Thong%20tin%20san%20pham/moldproof-ky.png","title":null,"width":null,"height":null}},{"type":"paragraph","content":[{"text":"Công nghệ Streamer","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Không chỉ ức chế đến 99,9% vi khuẩn, virus gây hại trong không khí, công nghệ Streamer còn ngăn ngừa ẩm mốc từ hơi nước đọng lại trong dàn lạnh, ức chế các chất gây mùi, các tác nhân gây ô nhiễm hiệu quả cho luồng khí luôn sạch sẽ, thoáng mát.","type":"text"}]},{"type":"paragraph","content":[{"text":"(hình ảnh chỉ mang tính chất minh họa)","type":"text","marks":[{"type":"italic"}]}]},{"type":"image","attrs":{"alt":"Công nghệ Streamer","src":"https://api-shop.daikin.com.vn:60443/storage/upload/media/SKUs/RA/FTKY-Z/Thong%20tin%20san%20pham/streamer-ky.png","title":null,"width":null,"height":null}},{"type":"paragraph","content":[{"text":"Lọc khí hiệu quả cùng phin lọc Enzyme Blue + PM2.5","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Máy còn được trang bị sẵn phin lọc 2 lớp, Enzyme Blue kết hợp PM2.5, nhờ đó mang lại hiệu quả lọc sạch không khí vượt trội, góp phần bảo vệ sức khỏe hô hấp của bạn.","type":"text"}]},{"type":"paragraph","content":[{"text":"Phin lọc này vừa có khả năng loại bỏ được các tác nhân gây mùi, chất gây dị ứng, nấm mốc, vi khuẩn và virus, đồng thời vừa có thể loại bỏ các hạt bụi mịn PM2.5 giúp tinh lọc không khí hiệu quả, từ đó duy trì bầu không khí sạch khuẩn và tươi mát trong căn phòng.","type":"text"}]},{"type":"paragraph","content":[{"text":"(hình ảnh chỉ mang tính chất minh họa)","type":"text","marks":[{"type":"italic"}]}]},{"type":"image","attrs":{"alt":"Lọc khí hiệu quả cùng phin lọc Enzyme Blue + PM2.5","src":"https://api-shop.daikin.com.vn:60443/storage/upload/media/SKUs/RA/FTKY-Z/Thong%20tin%20san%20pham/enzymeblue-ftky.png","title":null,"width":null,"height":null}},{"type":"paragraph","content":[{"text":"Mát lành lan tỏa nhờ luồng gió 3D và luồng gió thoải mái","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Luồng gió 3D đảo tự động 4 hướng từ trên xuống dưới, từ trái sang phải đầy nhịp nhàng sẽ giúp không gian phòng được làm mát một cách đồng đều và dễ chịu.","type":"text"}]},{"type":"paragraph","content":[{"text":"(hình ảnh chỉ mang tính chất minh họa)","type":"text","marks":[{"type":"italic"}]}]},{"type":"image","attrs":{"alt":"Mát lành lan tỏa nhờ luồng gió 3D và luồng gió thoải mái","src":"https://api-shop.daikin.com.vn:60443/storage/upload/media/SKUs/RA/FTKY-Z/Thong%20tin%20san%20pham/gio3d-ky.png","title":null,"width":null,"height":null}},{"type":"paragraph","content":[{"text":"Luồng gió Comfort","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Ngoài ra, máy còn có luồng gió thoải mái, ngăn gió thổi trực tiếp vào cơ thể người. Cài đặt này chuyển hướng luồng gió lên trên, không khí lạnh tràn xuống từ từ phủ lên người bạn như tấm chăn êm ái.","type":"text"}]},{"type":"paragraph","content":[{"text":"Cảm Biến Ẩm - Humidity Sensor","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Với cảm biến ẩm - Humidity Sensor bên trong dàn lạnh giúp tăng cường khả năng khử ẩm và làm lạnh nhanh hơn 25% so với dòng máy thông thường, giúp mang lại cảm giác thoải mái tối đa ngay khi thời tiết oi bức.","type":"text"}]},{"type":"paragraph","content":[{"text":"(hình ảnh chỉ mang tính chất minh họa)","type":"text","marks":[{"type":"italic"}]}]},{"type":"image","attrs":{"alt":"Cảm Biến Ẩm - Humidity Sensor","src":"https://api-shop.daikin.com.vn:60443/storage/upload/media/SKUs/RA/FTKY-Z/Thong%20tin%20san%20pham/humidity-sensor.png","title":null,"width":null,"height":null}},{"type":"paragraph","content":[{"text":"Mắt thần thông minh ngăn hao phí điện năng hiệu quả","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Mắt thần thông minh ngăn hao phí điện năng bằng việc phát hiện chuyển động của người trong phòng.","type":"text"},{"type":"hardBreak"},{"text":"Nếu không có chuyển động nào trong vòng 20 phút, máy sẽ tự động điều chỉnh tăng nhiệt độ cài đặt 2°C và giảm 2°C nếu phát hiện có người quay lại.","type":"text"}]},{"type":"paragraph","content":[{"text":"(hình ảnh chỉ mang tính chất minh họa)","type":"text","marks":[{"type":"italic"}]}]},{"type":"image","attrs":{"alt":"Mắt thần thông minh ngăn hao phí điện năng hiệu quả","src":"https://api-shop.daikin.com.vn:60443/storage/upload/media/SKUs/RA/FTKY-Z/Thong%20tin%20san%20pham/mat-than.png","title":null,"width":null,"height":null}},{"type":"paragraph","content":[{"text":"Tiết kiệm điện với công nghệ Inverter","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Daikin ứng dụng công nghệ tiết kiệm điện nhờ máy nén Swing, động cơ DC độc quyền và công nghệ Inverter. Trong đó, công nghệ Inverter sử dụng máy nén hiệu suất cao, tăng tải đến tần số tối đa khi vừa bật máy, giúp làm lạnh nhanh, vận hành êm ái, giảm hao phí điện năng nhờ đó giúp tiết kiệm tiền điện hằng tháng.","type":"text"}]},{"type":"paragraph","content":[{"text":"Giờ đây, bạn có thể yên tâm tận hưởng không gian mát lành mà không phải bận tâm về hóa đơn tiền điện hàng tháng. Bên cạnh đó, công nghệ Inverter cải tiến giúp máy vận hành êm ái, tạo nên không gian yên tĩnh để bạn có được giấc ngủ sâu và thoải mái suốt đêm dài","type":"text"}]},{"type":"image","attrs":{"alt":"Tiết kiệm điện với công nghệ Inverter","src":"https://api-shop.daikin.com.vn:60443/storage/upload/media/SKUs/RA/FTKY-Z/Thong%20tin%20san%20pham/cong-nghe-inverter-ky.png","title":null,"width":null,"height":null}},{"type":"paragraph","content":[{"text":"Dàn lạnh dàn nóng hoạt động êm ái","type":"text","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Dàn lạnh vận hành êm ái:","type":"text","marks":[{"type":"bold"}]},{"text":" Khi chọn tốc độ quạt thấp nhất, độ ồn hoạt động của dàn lạnh sẽ giảm xuống mức YÊN TĨNH và độ ồn hoạt động của dàn nóng cũng giảm xuống để giúp bạn có giấc ngủ ngon. Khi đó âm thanh vận hành của dàn lạnh chỉ từ 19dbA, êm như tiếng lá rơi.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Dàn nóng vận hành êm ái:","type":"text","marks":[{"type":"bold"}]},{"text":" Bằng cách thay đổi tần số và tốc độ quạt trên dàn nóng, dàn nóng sẽ vận hành êm ái và giảm độ ồn hơn. Chức năng này thuận tiện sử dụn vào ban đêm, ngoài ra khi sử dụng chức năng này còn giúp bạn tiết kiêm điện năng đáng kể.","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"(hình ảnh chỉ mang tính chất minh họa)","type":"text","marks":[{"type":"italic"}]}]},{"type":"image","attrs":{"alt":"Dàn lạnh dàn nóng hoạt động êm ái","src":"https://api-shop.daikin.com.vn:60443/storage/upload/media/SKUs/RA/FTKY-Z/Thong%20tin%20san%20pham/van-hanh-em-ai-ky.png","title":null,"width":null,"height":null}},{"type":"paragraph","content":[{"text":"Thiết kế vỏ dàn nóng giảm khe hở ngăn chặn thằn lằn xâm nhập","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Ở những vùng có khí hậu lạnh và đặc biệt ở nông thôn, thằn lằn và côn trùng rất thích xâm nhập dàn nóng để sưởi ấm, khiến bảng mạch biến tần hư hỏng thường xuyên. Vì thế, Daikin đưa ra cải tiến 03 đặc điểm ở dàn nóng :","type":"text"}]},{"type":"paragraph","content":[{"text":"• Thay đổi cấu trúc ở nắp van dịch vụ và ở các tấm kim loại để giảm khe hở","type":"text"}]},{"type":"paragraph","content":[{"text":"• Thay đổi hình dáng lỗ thoát nước ở đế máy sang hình oval","type":"text"}]},{"type":"paragraph","content":[{"text":"• Thêm miếng đệm vào vỏ máy bên phải và nắp van chặn để bít khe hở","type":"text"}]},{"type":"paragraph","content":[{"text":"Thiết kế kín kẽ chủ động bảo vệ bo mạch khỏi các tác nhân bên ngoài","type":"text","marks":[{"type":"italic"}]}]},{"type":"image","attrs":{"alt":"Thiết kế vỏ dàn nóng giảm khe hở ngăn chặn thằn lằn xâm nhập","src":"https://api-shop.daikin.com.vn:60443/storage/upload/media/SKUs/RA/FTKY-Z/Thong%20tin%20san%20pham/dan-nong-ben-bi.png","title":null,"width":null,"height":null}},{"type":"paragraph","content":[{"text":"Super PCB bảo vệ bo mạch khi điện áp thay đổi","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Tạm biệt nỗi lo ảnh hưởng đến tuổi thọ của máy hay xảy ra sự cố nguy hiểm do dòng điện không ổn định, mạch điện tử của sản phẩm chịu được điện áp lên đến 440V sẽ là biên độ cho phép hệ thống điều hòa không khí sẽ tự động ngắt khi điện áp cao hoặc thấp hơn phạm vi an toàn.","type":"text"}]},{"type":"paragraph","content":[{"text":"Mức chịu tải lớn lên đến 440V","type":"text","marks":[{"type":"italic"}]}]},{"type":"paragraph","content":[{"text":"(* Hình ảnh dàn nóng mang tính chất minh họa)","type":"text"}]},{"type":"paragraph","content":[{"text":"Lưu ý: chỉ bảo vệ điện áp 1 pha)","type":"text"}]},{"type":"image","attrs":{"alt":"Super PCB bảo vệ bo mạch khi điện áp thay đổi","src":"https://api-shop.daikin.com.vn:60443/storage/upload/media/SKUs/RA/FTKY-Z/Thong%20tin%20san%20pham/superpcb.png","title":null,"width":null,"height":null}},{"type":"paragraph","content":[{"text":"Dàn tản nhiệt ống đồng cánh nhôm phủ tĩnh điện","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Chỉ có trên dòng FTKY25/35","type":"text"}]},{"type":"paragraph","content":[{"text":"Bất chấp các tác nhân từ bên ngoài như nắng mưa, bụi, sương muối, nồm ẩm,… cánh dàn tản nhiệt sẽ không bị ăn mòn theo thời gian nhờ 2 lớp phủ tĩnh điện. Dù là ở ven biển, đồng bằng, núi cao hay thành thị, điều hòa Daikin bền vững cùng năm tháng.","type":"text"}]},{"type":"paragraph","content":[{"text":"Gấp đôi sự bảo vệ nhờ 2 lớp sơn phủ tĩnh điện","type":"text","marks":[{"type":"italic"}]}]},{"type":"image","attrs":{"alt":"Dàn tản nhiệt ống đồng cánh nhôm phủ tĩnh điện","src":"https://api-shop.daikin.com.vn:60443/storage/upload/media/SKUs/RA/FTKY-Z/Thong%20tin%20san%20pham/chong-an-mon.png","title":null,"width":null,"height":null}},{"type":"paragraph"}]}', ARRAY['https://gdzihzsjfczuggwpykjk.supabase.co/storage/v1/object/public/images/products/1775796890778-dzc11wxnf98.webp','https://gdzihzsjfczuggwpykjk.supabase.co/storage/v1/object/public/images/products/1775796903597-xarczo8jn2b.webp','https://gdzihzsjfczuggwpykjk.supabase.co/storage/v1/object/public/images/products/1775796904645-rh792rbrfsb.webp','https://gdzihzsjfczuggwpykjk.supabase.co/storage/v1/object/public/images/products/1775796905488-al672dlyti.webp','https://gdzihzsjfczuggwpykjk.supabase.co/storage/v1/object/public/images/products/1775796906082-9qooyi5snnq.webp','https://gdzihzsjfczuggwpykjk.supabase.co/storage/v1/object/public/images/products/1775796906945-g3u5nofx1d.webp','https://gdzihzsjfczuggwpykjk.supabase.co/storage/v1/object/public/images/products/1775796907267-ecn7xtggrxt.webp'], '11842593', '0.00', '11842593', '[{"label":"Công nghệ Inverter","value":"Có"},{"items":[{"unit":"HP","label":"","value":"1 "},{"unit":"kW","label":"","value":"2.70 (1.0 - 3.2) "},{"unit":"BTU","label":"","value":"9,200 (3,400-10,900)"}],"label":"Công suất làm lạnh"},{"items":[{"unit":"w","label":"","value":"700 (130-1,020)"}],"label":"Điện năng tiêu thụ"},{"items":[{"unit":"